// GENERATED from the original Find The Cats Luau sources (src/shared/Cats/Z1..Z7.lua) by a
// one-off extractor that copied name/kind/lore/hint VERBATIM. Do not hand-edit; the looks live in
// scripts/zones/zK.js. CATS[n] for n = 1..100 (CATS[0] is null so the index is the cat number).

export const CATS = Object.freeze([
  null,
  Object.freeze({"name":"Biscuit","kind":"Bread Loaf Cat","lore":"Biscuit sat down in the meadow one sunny morning, tucked in all four paws, and has not moved since. Scientists say he is 40 percent cat and 60 percent sourdough. His top went golden brown from the sun and now smells exactly like a bakery, which is why a butter pat appeared on his head and nobody can explain it. He believes he is the best bread in the whole kingdom and introduces himself to every pigeon. If you try to slice him he just says 'no' in a very deep voice. He is the first cat everyone finds and he is SO proud of that.","hint":"Just past the rainbow arch, loafing on the side of the path. You literally cannot miss him."}), // 1
  Object.freeze({"name":"Kevin","kind":"Orange Cat","lore":"Kevin is an orange cat, which means the whole family shares exactly one brain cell, and today it is NOT Kevin's turn. You can see the brain cell floating above his head, glowing, waiting to be returned to his cousin. Kevin has spent eleven hours chasing one butterfly through the flower field. The butterfly is sitting on his nose. He has not noticed. Once he tried to eat a bee and the bee felt sorry for him and left. He is extremely happy at all times and we should all learn from Kevin. Or not. Probably not.","hint":"Somewhere in the big flower field, chasing a butterfly that is already on his nose."}), // 2
  Object.freeze({"name":"Sunny","kind":"Sunbeam Cat","lore":"Sunny follows the one perfect sunbeam that moves across Cozy Meadow every day. When the sunbeam moves, Sunny moves. When the sunbeam stops, Sunny melts into a flat puddle of fur and does not move for six to nine business hours. She has been asleep so long that tiny dream bubbles float out of her head and pop on passing bees. Rumour says she once got so warm she turned into a pancake and a family tried to put syrup on her. She was fine. She did not wake up.","hint":"Melted flat in a glowing sunbeam on the grass, west of the pond."}), // 3
  Object.freeze({"name":"Oscar","kind":"Cat In A Box","lore":"Oscar was delivered to Cozy Meadow by mistake. The label said 'One (1) Pair Of Socks'. He refused to leave the box, so the box became his house, his office, his castle and his entire personality. He sits in the middle of the road with a FREE CAT sign that he wrote himself, but whenever anyone tries to take him home he says 'actually the box comes too' and the deal falls apart. He thinks boxes are portals. He is right about one of them. He will not say which one.","hint":"Sitting in a cardboard box right in the middle of the main path. He made a sign."}), // 4
  Object.freeze({"name":"Pickles","kind":"Picnic Thief Cat","lore":"Wanted in four counties for crimes against lunch. Pickles wears a tiny black mask so nobody recognises him, even though he is the only white cat in Cozy Meadow and also signs his name on every crime scene. He has stolen 3,000 sandwiches, two pies and one entire picnic blanket while the family was still sitting on it. His favourite sandwich is ham, cheese, lettuce, tomato and 'whatever you are holding right now'. When caught he simply says 'it was like that when I got here' and keeps chewing.","hint":"Sitting right on top of the picnic table, holding something that is definitely not his."}), // 5
  Object.freeze({"name":"Hank","kind":"Hay Bale Cat","lore":"Hank is either a cat that looks like a hay bale or a hay bale that looks like a cat. The farmer has been trying to figure it out for three years. Hank is fluffy, square, itchy and very proud of all four of those things. Horses keep trying to eat him and he keeps saying 'excuse me I am a GENTLEMAN'. He has straw sticking out of his head that he calls his 'hairstyle'. Once he got stacked with the other bales and nobody found him until spring. He says it was the best nap of his life.","hint":"In front of the barn, pretending to be one of the hay bales. He is the one with a face."}), // 6
  Object.freeze({"name":"Daisy","kind":"Flower Crown Cat","lore":"Daisy crowned herself ruler of the flower field after winning a beauty contest that she organised, judged and was the only contestant in. She wears a crown of real flowers which she replaces every morning, so the flower field is slowly getting smaller. Her eyes are permanently hearts because she is in love with herself. She speaks only in 'uwu' and once made a bee cry by calling it 'a wittle buzzy bean'. She has a royal decree that says all butterflies must curtsy. They do not.","hint":"Posing in the flower field like it's a photoshoot. Look for the flower crown."}), // 7
  Object.freeze({"name":"Tilly","kind":"Cat Who Thinks It Is A Duck","lore":"Tilly was raised by ducks and nobody ever told him. He has a beak (it is a traffic cone he found), little wings (they are oven mitts) and he floats in the pond all day saying 'QUACK' in a voice that is clearly 'meow'. The real ducks are too polite to correct him. He tried to migrate south for the winter once and got as far as the picnic table. Every time he sees bread he gets very emotional. His best friend is a rubber duck who he thinks is his little brother. Honestly, valid.","hint":"Floating in the pond, quacking. Very badly."}), // 8
  Object.freeze({"name":"Muffin","kind":"Cow Cat","lore":"Muffin lives in the cow pen and is 100 percent sure she is a cow. She has spots, little horns and a cow bell, and she says 'MOOOO' so loudly the windmill spins faster. The farmer tried milking her once and got chocolate milk, so now he is too scared to ask questions. She eats grass for breakfast, lunch and dinner and then proudly leaves a hairball on the barn floor as a thank-you gift. The real cows have formed a committee about her. The committee is also mostly her.","hint":"In the fenced cow pen next to the barn. Ding ding goes the bell."}), // 9
  Object.freeze({"name":"Pete","kind":"Wannabe Pilot Cat","lore":"Pete lives next to the windmill and believes that if he spins his propeller hat fast enough he will finally fly. So far he has achieved: zero flights, nine dizzy spells and one very confused bird. He wears flight goggles to look professional and has given himself the rank of Supreme Air Admiral. He tells everyone the windmill is 'just a big version of me'. On windy days his hat spins on its own and he lifts maybe one centimetre off the ground and screams 'I AM THE SKY' for an hour.","hint":"Hanging around at the foot of the windmill, waiting for a strong wind."}), // 10
  Object.freeze({"name":"Scout","kind":"Scarecrow Cat","lore":"Scout was hired to guard the vegetable garden from crows. Unfortunately, Scout is extremely friendly and has instead invited every crow in the county to a weekly tea party. One crow lives on his hat full-time and pays rent in shiny buttons. His button eyes cannot blink, which he says makes him 'the best at staring contests in the world'. He has stuffing coming out of his sleeves and insists it is fashion. The vegetables are all gone, but everyone agrees the tea parties are lovely.","hint":"Standing on a post in the middle of the vegetable garden, arms out. There's a crow on his hat."}), // 11
  Object.freeze({"name":"Barry","kind":"Lookout Cat","lore":"Barry climbed to the top of Lookout Hill to keep watch over Cozy Meadow. Watch for what? He does not know. He has been looking through his binoculars backwards for six years, so everything looks tiny and he thinks the whole world is a model train set. He writes reports like 'Barn: still a barn' and 'Sky: suspicious'. He wears an explorer hat even though he has never explored anything except the snack drawer. If you climb his tower and use the telescope you might see more than Barry ever did.","hint":"At the very top of Lookout Hill, next to the wooden tower. Walk up the big green hill."}), // 12
  Object.freeze({"name":"Wendy","kind":"Cat That Is A Weathervane","lore":"Wendy climbed onto the barn roof to look at a bird in 1997 and decided to stay forever. Over the years she has turned a lovely shade of copper green and now officially works as the meadow's weathervane. She points wherever the wind blows, except when there is food, in which case she points at the food. Her forecasts are always the same: 'Wind: yes. Snacks: needed.' The farmer has tried to bring her down with a ladder nine times but every time she spins really fast and he gets dizzy and gives up.","hint":"Up on the barn roof, spinning with the wind. Those hay bales stacked by the barn look like stairs..."}), // 13
  Object.freeze({"name":"Steve","kind":"Soggy Dock Cat","lore":"Steve is the only cat in history who LIKES being wet. He lives under the old dock in the pond with his snorkel, his goggles and his best friend, a piece of seaweed named Greg. He claims he is a professional marine biologist and his research so far is: 'fish are wet'. He is always grumpy because people keep walking on the dock above his head going CLOMP CLOMP CLOMP. If you visit him, bring a towel, not for him, for you, because he will shake himself dry right next to you on purpose.","hint":"Under the wooden dock, down in the pond. You'll have to get your feet wet."}), // 14
  Object.freeze({"name":"Toby","kind":"Toaster Cat","lore":"Toby is a toaster. He is also a cat. Scientists are still arguing about which one he was first. Every morning he pops two slices of toast out of his head and yells 'BREAKFAST IS SERVED, PEASANTS' even though nobody asked. His tail is a power cord and he plugs it into random walls to 'feel alive'. He once made toast so crispy it became a charcoal briquette and he put it on his fridge like a trophy. Do not put a bagel in him. He will be offended for three to five business days.","hint":"Someone left him plugged in on the kitchen counter of the yellow house. Just walk in."}), // 15
  Object.freeze({"name":"Parker","kind":"Traffic Cone Cat","lore":"Parker was a normal traffic cone until a construction worker said 'hey kitty' to him one time and he simply decided to become a cat. Now he guards road works and says 'no' to every car, bike and pigeon. He has never moved in his whole life because he thinks if he moves the road will explode. He has two reflective stripes and calls them his 'abs'. His dream is to be stacked on top of another cone so he can finally be tall. Honk if you love him. Actually please don't honk, he gets scared.","hint":"Road works! He is guarding the very top of the scaffolding behind the barriers. Climb the crates."}), // 16
  Object.freeze({"name":"Latte","kind":"Barista Cat","lore":"Latte works at The Purrcolator café and has spelled every single customer's name wrong on purpose since 2019. Your name is Kevin? Your cup now says 'Meowvin'. She only knows how to draw one thing in latte foam and it is a fish, every time, even on hot chocolate. She has a tiny mustache that she claims is 'for the vibe'. She is extremely sleepy because she drinks zero coffee, she says coffee is 'for customers only, I am a professional'. Tip jar accepts coins, fish and compliments.","hint":"Behind the counter of The Purrcolator café. Staff only (lol, nobody checks)."}), // 17
  Object.freeze({"name":"Gus","kind":"Cat That Is A Bus","lore":"Gus is a bus. It is also a cat. It is mostly a bus. It was supposed to drive Route 9 every ten minutes but it has not shown up once in forty years because it keeps stopping to nap on warm roofs. The timetable at the bus stop just says 'NEVER' now. Passengers ride inside it for free but it purrs so loud the windows rattle and everybody falls asleep and misses their stop. It has four wheels and zero paws and is honestly fine with that. Beep beep meow.","hint":"It is napping on the roof of its own bus stop shelter. Climb the bench and the bin."}), // 18
  Object.freeze({"name":"Benny","kind":"Garbage Can Cat","lore":"Benny lives in a bin. Not near a bin. IN a bin. He says it is 'a studio apartment with a lid'. He wears the lid as a hat and a banana peel as a scarf and he thinks he looks amazing (he does not). Every Thursday the garbage truck comes and Benny screams 'NOT TODAY' and holds the lid shut with all four paws. He collects fish bones like trading cards and has a shiny one he will not let anybody touch. He smells. He knows. He is proud.","hint":"Bin day! Open the bins in the alley next to the diner. One of them smells extra fishy..."}), // 19
  Object.freeze({"name":"Finn","kind":"Fish Stick Cat","lore":"Finn is a cat made entirely of breaded fish sticks, which is a huge problem because cats LOVE fish sticks. Every other cat in Catford keeps trying to lick him. He hides in the ice display at the fish market pretending to be on sale, and he gets very upset when nobody buys him. He wears a captain hat even though he has never seen the sea. His catchphrase is 'Crunch crunch, I'm in charge.' Serve with a lemon wedge. Wait, no. Don't.","hint":"He is lying in the ice with the other fish, behind a stall counter at the Fish Market."}), // 20
  Object.freeze({"name":"Sandy","kind":"Sandcastle Cat","lore":"Sandy is a sandcastle shaped like a cat, or a cat shaped like a sandcastle, nobody can tell. He was built by a toddler at the Catford playground who then got bored and left, so Sandy declared himself king of the whole playground. He lives at the top of the climbing tower and rules the slide with an iron paw. His biggest fear is rain. His second biggest fear is the sandbox, because 'that is where the OTHER cats go'. He will not elaborate. He is always slightly crumbling.","hint":"King of the playground! Climb the ladder of the play tower in the park."}), // 21
  Object.freeze({"name":"Bubbles","kind":"Fishbowl Astronaut Cat","lore":"Bubbles stuck her head in a fishbowl at the Pawsome Pets shop and it got stuck, so now she is an astronaut. That is how astronauts work, she says. The goldfish who lives in the bowl, Gerald, is now her co-pilot and they are not friends. She practices for space by sitting on the highest shelf in the store and saying 'one small step for cat' before refusing to step anywhere. She has two oxygen tanks on her back. They are empty spray cans. Ground control to Major Meow, please come down, the store is closing.","hint":"Up on the very top shelf in Pawsome Pets. Shelves make great stairs."}), // 22
  Object.freeze({"name":"Belle","kind":"Inflatable Pool Floatie Cat","lore":"Belle is a blow-up pool floatie shaped like a cat, and she is VERY full of herself (and air). She floats under the Whisker Park bridge all day because the sun makes her squeaky. Her biggest fears are cactuses, pins, pinecones and the hedgehog who lives by the swings. She has a big hole in her middle and says it is 'where she keeps her feelings'. If you sit on her she makes a long squeaky noise and everybody looks at the dog. The dog did not do it. She is a boat, a cat and a balloon at the same time, so she calls herself 'the main character'.","hint":"Floating in the park pond, hiding in the shade UNDER the bridge. Walk on the water."}), // 23
  Object.freeze({"name":"Dexter","kind":"Satellite Dish Cat","lore":"Dexter is a satellite dish who woke up one morning as a cat. Or a cat who woke up as a satellite dish. Either way, her whole face is a dish now. She lives on top of the tallest house in Catford and picks up exactly ONE channel: a 24-hour cooking show about fish. She watches it all day and drools on the roof. When the wind moves her she loses signal and yells 'WHO MOVED ME' at the pigeons. Her tail is a TV cable and she once plugged it into the neighbour's toaster by accident. The neighbour is Toby. They do not talk about it.","hint":"On top of the little tower of the tallest house. Get up on the first roof and jump across the rooftops."}), // 24
  Object.freeze({"name":"Walter","kind":"Cat That Is A Clock","lore":"Walter lives at the very top of the Catford clock tower, right under the big bell, and he is the reason every clock in town is wrong. He counts the seconds out loud, but he only knows the numbers one, two and 'a lot'. At midnight he goes BONG and then says 'sorry' every single time. His pendulum is actually his tail and he swings it so hard he once launched a pigeon into next Tuesday. Do not ask him the time. He will say 'nap o'clock' and he will be correct.","hint":"Highest point of the clock tower, under the bell. Jump up the ledges that spiral around it."}), // 25
  Object.freeze({"name":"Stanley","kind":"Traffic Light Cat","lore":"Stanley is a traffic light with cat ears and he has three eyes: red, yellow and green. Nobody knows which one he actually sees out of. When he is angry he goes red, when he is nervous he goes yellow, and when he sees a fish he goes green and runs across the road without looking, which is very bad, children. He invented the Cat Signal so other cats know when it is safe to cross, but he made the pattern so complicated that nobody has crossed the road since.","hint":"Locked next to the Cat Signal box at the big crossroads. Pull the levers in the order the Cat Signal flashes."}), // 26
  Object.freeze({"name":"Milo","kind":"Lost & Found Cat","lore":"Milo is made of everything anyone has ever lost in Catford. One odd sock, one mitten, a pair of glasses, a phone with 1% battery and a broken umbrella. If you lost something, it is probably part of him now, and he will NOT give it back. He lives in the Lost & Found kiosk, which is locked, because the Mayor lost the key. Classic. Milo says the key is 'with the biggest fish in town' but he is a little smug about it. He once found himself and immediately lost himself again.","hint":"Locked inside the Lost & Found kiosk. The key is with the biggest fish in town. Look up."}), // 27
  Object.freeze({"name":"Gary","kind":"Sewer Alligator Cat","lore":"Everyone in Catford says there is an alligator in the sewers. They are wrong. It is Gary, a cat who watched one nature documentary and decided to become an alligator. He has a long snout made of cardboard, a hard hat with a little lamp, and the scariest teeth in town (they are painted on). He lurks in the very middle of the sewer maze going 'snap snap' quietly to himself. He has never snapped anything. He is terrified of rubber ducks. The fish market drains into his room, which he calls 'room service'.","hint":"Deep in the sewer maze under the town. Find the open manhole and keep one paw on the wall."}), // 28
  Object.freeze({"name":"Boo","kind":"Ghost Cat (Bad At Haunting)","lore":"Boo died of pure embarrassment in 1842 after falling off a bookshelf in front of dinner guests, and he has haunted the manor ever since. Unfortunately he is TERRIBLE at haunting. He floats up to people, whispers 'boo' in a tiny voice, then apologizes and offers them his little lantern so they don't trip in the dark. He read that ghosts should be 'spooky and mysterious', but mostly he looks like a sleepy cloud wearing a bedsheet. His only goal in the afterlife is to scare ONE person. Please act scared. He is trying so hard.","hint":"Ghosts float. So do some of the gravestones around the big dead tree."}), // 29
  Object.freeze({"name":"Bones","kind":"Skeleton Cat (No Cat, Just Bones)","lore":"Bones is a Skeleton Cat, which means there is no cat. It is just the bones. Nobody knows where the rest of him went and he refuses to talk about it. He drinks seventeen glasses of milk a day 'for strong bones' even though the milk falls straight through him onto the floor. When he purrs he rattles, which sounds like someone dropping a bag of spoons down the stairs. He sleeps in a locked coffin in the crypt because he once got mistaken for a xylophone at a party and he is still not over it.","hint":"Locked in a coffin in the crypt. The groundskeeper leaves keys on rooftops."}), // 30
  Object.freeze({"name":"Vinnie","kind":"Vampire Cat (Scared Of Garlic Bread)","lore":"Vinnie is a 600-year-old vampire cat who sleeps in a coffin, wears a cape indoors and says 'I vant to drink your... tuna juice.' He is terrifying in every way EXCEPT one: he is deathly afraid of garlic bread. Not garlic. Garlic BREAD. Specifically the buttery kind. The second someone makes a snack he dives back into his coffin and screams 'NOT THE CARBS' at a pitch only dogs can hear. He has fangs, glowing red eyes and a nervous sweat drop that never goes away. He has no reflection either, so his fur is always a little bit messy.","hint":"He won't leave his coffin while there is garlic bread anywhere near the dining room."}), // 31
  Object.freeze({"name":"Pumpkin","kind":"Pumpkin Cat","lore":"Pumpkin was a normal orange cat until a witch sneezed on him during a pumpkin carving contest. Now he is 60% cat, 40% pumpkin and 100% sure he should have won the contest. His face glows when he is happy, angry or hungry, which is always. He smells like pumpkin spice and gets offended when people try to put him on a porch. Every October he becomes famous for exactly one month, then spends November to September sitting in a field telling crows that he 'used to be a really big deal'.","hint":"The pumpkins behind the manor want to be booped in a certain order."}), // 32
  Object.freeze({"name":"Jasper","kind":"Cursed Cat Image","lore":"Nobody knows who took this photo. Nobody knows WHY the cat has human teeth. Nobody knows why one eye is the size of a dinner plate and the other one is a tiny red dot. Jasper has been saved, re-saved and screenshotted so many times that it turned into pure JPEG crust and became self-aware. It lives on the top shelf of the library because that is where people hide things they never want to look at again. If you stare at it too long, your screen brightness goes down by itself. Do not set it as your wallpaper.","hint":"High up in the library. Giant books make great stairs."}), // 33
  Object.freeze({"name":"Ziggy","kind":"Mummy Cat (Wrapped In Toilet Paper)","lore":"Ziggy was wrapped up 3,000 years ago by ancient cat priests who did not have bandages, so they used toilet paper. Two-ply. Very fancy for the time. She has been slowly unrolling ever since and leaves a trail of tissue everywhere she goes, which is why the manor basement is so clogged. Her eyes glow green because she ate a glow stick in 1998 thinking it was a fancy noodle. She carries a spare roll at all times 'for emergencies' and refuses to explain what kind of emergencies. Do not ask. She will tell you.","hint":"Under the manor, past a LOT of green goo."}), // 34
  Object.freeze({"name":"Brewster","kind":"Cat Soup (Witch's Leftovers)","lore":"Brewster belonged to a witch who once asked him to 'keep an eye on the soup'. He took this extremely literally and climbed in. That was 200 years ago. He has been sitting in a bubbling cauldron of green slime ever since and says it is the best hot tub he has ever had. He wears the witch's hat because she left without it and he thinks it makes him look 'mysterious and expensive'. Every few minutes a big bubble pops in the slime and he says 'that was the soup, not me'. It was him.","hint":"Witches live in tall towers. Do NOT swim in the moat."}), // 35
  Object.freeze({"name":"Bean","kind":"Zombie Cat (Wants Treaaats)","lore":"Bean rose from his grave one Halloween and shuffled around the graveyard groaning 'BRAAAINS'... until everyone realized he was actually groaning 'TREAAATS'. He is a zombie cat with stitches, a crooked grin and blue shorts he definitely did not have when he was buried. He walks with his arms stuck straight out because he thinks that is the rule. He only remembers numbers from graves with fish carved on them, which is sad but also weirdly useful. He keeps a bag of treats tied to his paw 'for later'. There is no later. He eats them immediately.","hint":"The dead in the graveyard remember a code. The crypt explains how to read it."}), // 36
  Object.freeze({"name":"Ella","kind":"Haunted Portrait Cat (Eyes Follow You)","lore":"Ella is the most important portrait in the manor, and she will remind you of that. She lives INSIDE her painting and only wakes up when somebody says the family word, which everyone keeps forgetting, which she finds very rude. Her eyes follow you around the room. She says this is 'polite'. Everyone else says it is 'deeply upsetting'. She wears a ruff collar the size of a pizza, pearls she won from a duchess at cards, and a hat with a feather that is technically a whole pigeon. Stand up straight. She is watching.","hint":"An empty frame in the upstairs gallery. Her family knows the word."}), // 37
  Object.freeze({"name":"Barkley","kind":"Werecat (Turns Into A Golden Retriever)","lore":"Barkley is a perfectly normal cat for 29 days a month. Then the full moon rises and he transforms into... a golden retriever. Floppy ears. Tongue out. Tail going a million miles an hour. He fetches sticks, rolls in mud and tells everyone they are a good boy, including the furniture. The other monsters keep him in a locked moon cage because the last time he got out he licked the vampire. The worst part is that he remembers everything the next morning and has to live with the fact that he played fetch for four hours. With a sock.","hint":"Count the candles. The note by the moon cage says which rooms."}), // 38
  Object.freeze({"name":"Phoebe","kind":"Dramatic Organ Cat (Half Mask)","lore":"Deep inside the music room lives the Phantom of the Litterbox, a very dramatic cat in a half-mask who plays the cursed organ at 3 a.m. and calls it 'art'. He only knows one song. He has played it 40,000 times. He hides half his face because he once sneezed in the middle of a solo and has never emotionally recovered. He throws roses at anyone who claps, and also at people who don't clap, just to be safe. If you play his song correctly he will burst out of his cage, cry loudly and yell 'FINALLY, someone who UNDERSTANDS me!'","hint":"The cursed organ's keys are scrambled. Listen to it, or watch the meter."}), // 39
  Object.freeze({"name":"Atticus","kind":"Upside-Down Bat Cat","lore":"Atticus is half cat, half bat and fully confused about it. He sleeps upside down in the attic rafters because the bat half insists, but the cat half keeps landing on its feet, so every morning he lands on the ceiling, which is exhausting. He has wings but is afraid of heights. He has fangs but is a vegetarian. He tries echolocation but mostly just yells 'MEOW' at walls and waits to see what happens. His favourite snack is moths. His favourite hobby is falling. If he does a flip, please clap. He practiced for weeks.","hint":"Hangs out where the rafters are. Don't touch the purple goo."}), // 40
  Object.freeze({"name":"Percy","kind":"Headless Knight Cat","lore":"Percy was the bravest knight cat in the land until he tried to squeeze his head through a fence to reach a sandwich. The sandwich was fine. The head was not. Now he wanders the manor grounds in shiny armor with spooky green fire coming out of his neck, carrying his own head under his arm like a bowling ball. The head does the talking and the body does the walking, and they argue constantly. He keeps dropping the head in the hedge maze. If you find it, please give it back. It is kind of important.","hint":"He lost his head in the hedge maze. Don't die on the way back."}), // 41
  Object.freeze({"name":"Lionel","kind":"Final Boss Cat Of The Manor","lore":"Lionel is the ancient, all-powerful lord of the manor who hid his soul inside a magic litterbox so he could live forever. This was a terrible plan, because now his soul smells. He floats on a litterbox throne in a secret room behind the library, wearing a crown, waving a scoop-shaped scepter and announcing 'I AM THE MASTER OF THIS HOUSE' to absolutely nobody. Every ghost, zombie and pumpkin in the manor works for him, but only because he pays in treats. His laser eyes are terrifying. His evil laugh is just 'mrrp mrrp mrrp'. Bow anyway.","hint":"Some books are not for reading. Three lost pages are hidden around the manor."}), // 42
  Object.freeze({"name":"Ember","kind":"Lava Cat","lore":"Ember was a normal cat until she sat on a volcano to warm her butt and just... never got up. Now she is 90% lava, 10% attitude and 0% safe to pet. She leaves little fire pawprints everywhere and the lab had to replace the carpet 47 times. Her favourite food is hot sauce. Her second favourite food is the carpet. She does not understand why nobody wants to cuddle her and honestly that is a her problem. If she purrs too loud the volcano erupts, so please, do NOT scratch behind her ears.","hint":"She lives on a rock island in the middle of the lava lake. Mind your step. Every step."}), // 43
  Object.freeze({"name":"Rusty","kind":"Conveyor Belt Cat","lore":"Rusty fell asleep on a factory conveyor belt in 2019 and has been riding it ever since. He has gone around the factory roughly nine million times. He has been scanned, boxed, unboxed, labelled FRAGILE and once accidentally shipped to Belgium (they sent him back with a waffle). He thinks the belt is a very long bed that loves him. Every time someone tries to take him off, he yowls until they put him back. His price tag says 4.99. Nobody knows who priced him. Nobody dares to buy him.","hint":"He is riding the conveyor belts inside the factory. Run against the belts and dodge the crushers."}), // 44
  Object.freeze({"name":"Max","kind":"Atom Cat","lore":"Max is not one cat. Max is three electrons, four protons and one very confused neutron who all agreed to be a cat together. Scientists say an atom is mostly empty space, which explains why Max forgets everything you tell it. When it gets excited its electrons zoom around so fast that it accidentally splits into two smaller, angrier cats. It glows blue at night, which is cool, and also a bit radioactive, which is less cool. Do not lick Max. We have a poster about this.","hint":"Locked at the Reactor Control board in the lab courtyard. Turn every light OFF."}), // 45
  Object.freeze({"name":"Robbie","kind":"Robot Cat","lore":"Robbie was built to replace real cats, which went great until it learned how to knock things off tables. Now it does it at 400 cups per minute. It runs on two AA batteries and pure spite. Its only voice line is MEOW.EXE HAS STOPPED WORKING. It loves playing memory games because it is a computer and it never, ever forgets. It will remember the time you beat it. It will remember forever. Please clap when it does a backflip. It cannot do a backflip.","hint":"The robot in the lab courtyard wants to play Simon Says. Repeat its flashing pattern 6 times."}), // 46
  Object.freeze({"name":"Sam","kind":"Clone Cat","lore":"The lab tried to clone the perfect cat. Clones #1 to #46 came out as a toaster, a sock, three potatoes and forty-one deeply disappointing puddles. Then came #47: technically a cat, slightly green, and convinced it is the original. It is not the original. Nobody knows where the original went. #47 spends its days floating in a jar, staring at you, mouthing the words I AM THE REAL ONE. Its DNA had to be sorted back into order with a sliding puzzle, which is not how science works. Science said nothing.","hint":"Floating in a cloning vat in the lab courtyard. Sort the DNA samples 1 to 8."}), // 47
  Object.freeze({"name":"Apollo","kind":"Rocket Cat","lore":"Apollo wanted to be the first cat on the moon. He strapped himself to a rocket, pressed the big red button, flew exactly eleven centimetres and then fell asleep on top of the launch tower because the countdown was too long. He refuses to come down until NASA calls him personally. He wears his goggles at all times, including in the bath. He calls everyone 'ground control'. His mission patch says ONE SMALL STEP FOR CAT, ONE GIANT NAP FOR CATKIND, which he made himself out of a sticker.","hint":"He is napping on top of the launch tower next to the big rocket. Climb the gantry."}), // 48
  Object.freeze({"name":"Ollie","kind":"Cat Made Of Science","lore":"Ollie is what happens when you pour every chemical in the lab into one beaker and yell 'BE A CAT'. It is 40% glass, 30% bubbling green goo, 20% math and 10% that one smell from the science room. It speeds up every reaction it touches, so if you tell it a joke it laughs before you finish. It solves equations for fun and leaves the answers on the fridge. Its goggles are not optional. They are glued on. Do not ask about the incident with the baking soda volcano.","hint":"Caged at the Science Keypad in the lab courtyard. Solve the symbol equations."}), // 49
  Object.freeze({"name":"Patty","kind":"Laser Cat","lore":"Patty is the lab's security guard. She has laser eyes, a laser backpack and a laser tail, and absolutely no idea how to turn any of them off. She spent her whole life chasing the red dot until one day she caught it, absorbed its power and BECAME the red dot. Now other cats chase HER. She guards the security corridor with a grid of lasers she made herself, mostly so nobody steals her snacks. She has never once said anything except 'pew'. It is, to be fair, enough.","hint":"At the far end of the Security Corridor next to the lab. Jump, wait, dodge. Pew."}), // 50
  Object.freeze({"name":"Sparky","kind":"Electric Fuse Cat","lore":"Sparky licked a power socket once. Just once. That was all it took. Now his fur is permanently standing up, his tail is an extension cord and he can charge a phone by sitting on it (please do not let him sit on your phone). He powers the entire volcano lab, which is why the lights flicker every time he sneezes. Someone stole his five fuses and hid them all over Mount Hairball, so now he is stuck in the fuse box, buzzing angrily. He smells like burnt toast. Always.","hint":"Stuck in the fuse box at the power station. Find all 5 fuses, then sort them like stars."}), // 51
  Object.freeze({"name":"Winston","kind":"Volcano Hot Tub Cat","lore":"Winston climbed all the way to the top of Mount Hairball, looked into the crater full of boiling lava and said 'ah yes, a jacuzzi'. He has been relaxing there ever since, wearing sunglasses, a towel on his head and the smug face of someone who has never paid rent. He orders lemonade by yelling at passing scientists. The rubber duck is called Gerald and is fireproof, unlike Gerald 1 through Gerald 6. He says the lava is 'a bit chilly today, actually'.","hint":"Relaxing in the crater at the very top of the volcano. It's a long climb. Checkpoints help."}), // 52
  Object.freeze({"name":"Zoe","kind":"Lab Test Subject Cat","lore":"Zoe was the very first cat to volunteer for an experiment. It did not volunteer. It walked into the wrong room looking for snacks. Now its brain lives in a glass dome on top of its head, hooked up to a car battery, and it is 3000% smarter. It can do long division, speak Morse code and open any door with a code. It still cannot open a bag of treats by itself, which it finds deeply humiliating. It is kept in the most secret room of the lab, three locked doors deep, for its own safety. And ours.","hint":"Behind 3 locked doors in the Secure Wing of the lab. Every room hides the code for the next door."}), // 53
  Object.freeze({"name":"Charlie","kind":"Periodic Table Cat","lore":"Scientists searched for years for the missing element between Carbon and absolutely nothing. They found it under the lab fridge: CHONK, Element 0, the heaviest substance known to science. One CHONK weighs about as much as four normal cats or one medium fridge. It is made of Carbon, Hydrogen, Oxygen, Nitrogen and Potassium, which coincidentally spells its own name, which it thinks makes it a genius. CHONK does not move. CHONK is moved around. Its half-life is one nap. Its full life is several naps.","hint":"Caged by the Periodic Table wall in the lab courtyard. Five element notes are scattered across the zone."}), // 54
  Object.freeze({"name":"Iris","kind":"Prism Cat","lore":"Iris is a cat made of pure crystal. When light goes into Iris, a rainbow comes out of its butt. It is extremely proud of this and does it at every party whether anyone asked or not. Iris is so transparent you can see what it had for breakfast (a flashlight). It only drinks purple light because it says white light is 'basic'. The lab locked it up after it bounced a laser off itself and accidentally gave the coffee machine a tan. It is technically a disco ball with whiskers.","hint":"In the Prism Lab past the lava river. Find the laser's power key first, then bend the beam."}), // 55
  Object.freeze({"name":"Whiskers","kind":"Time Travel Cat","lore":"Whiskers sat on the lab's time machine at exactly the wrong moment and got stuck at 2:50 PM on a random Tuesday in the past. It has a clock in its tummy that ticks louder when it is hungry. It has already eaten tomorrow's dinner, met its own grandkitten and accidentally invented the cardboard box in the year 1066. It tells everyone 'I've seen how this ends' and then refuses to explain. The scientist's diary is the only record of when it vanished, so read carefully. Do not be late. Or early.","hint":"Lost in time. Read the 4 diary pages around the zone, then set the time machine's dials (north side)."}), // 56
  Object.freeze({"name":"Frank","kind":"Mad Scientist Cat","lore":"Frank built the whole volcano lab, every cat in it and most of the lava. His PhD is in Advanced Mischief from the University of Knocking Stuff Over. He shouts IT'S ALIVE at everything, including toast. His ultimate plan is to launch himself into orbit and build a space station shaped like a giant tuna can, so he can rule the world from above while napping. He will only meet visitors who can fuel his rocket and crack his launch code. His evil laugh is just him saying 'mwahaha' really slowly.","hint":"He is already in orbit. Fuel the rocket with 3 canisters, crack the launch code, ride the crew lift."}), // 57
  Object.freeze({"name":"Nell","kind":"Cat That Is Literally The Word nil","lore":"nil is not a cat. nil is the word nil, written in lowercase, standing on tiny paws. The dot on the i is its head. Scientists asked nil what it was and it replied \"attempt to index nil with 'meow'\" and then crashed three computers. nil has no value, no type and no feelings, except on Tuesdays, when it feels slightly undefined. Every programmer has met nil at least once, usually at 3 AM, usually screaming. It eats null pointers for breakfast and it never, ever returns.","hint":"The path to nil is there. You just can't see it. Look down."}), // 58
  Object.freeze({"name":"Nova","kind":"Missing Texture Cat","lore":"You tried to load a cat. The server said no. What you got instead is Nova, a cube-shaped kitty covered in the pink-and-black checkerboard that games show when a texture goes missing. It has X eyes because it is technically a broken link. A giant question mark follows it everywhere like a sad balloon. If you refresh the page it is still there. If you clear your cache it is still there. It has accepted that it does not exist and is honestly vibing about it.","hint":"The page you are looking for is behind a wall that doesn't exist."}), // 59
  Object.freeze({"name":"Echo","kind":"Frozen Program Cat (Lagging)","lore":"Echo was a perfectly normal desktop pet until somebody tried to pet it, feed it and open forty browser tabs at the same time. Now it is frozen forever in the middle of a step, one paw in the air, with a frozen hourglass stuck above its head and a smear of see-through copies trailing behind it, like a window somebody dragged across a crashed screen. Its eyes point in two different directions because half of its brain is still loading. Pressing OK does nothing. Pressing Cancel does nothing. Pressing every button in the right order supposedly reboots it, which is the only tech support it has ever received.","hint":"Replay the crash log. The timestamps know the order."}), // 60
  Object.freeze({"name":"Misty","kind":"Invisible Cat","lore":"Misty is an invisible cat, which is a huge problem for him because he is also extremely fancy. He wears a floating top hat, a floating bow tie and floating sunglasses so people know where to send the compliments. Every time someone walks through him he says \"excuse me\" in a tiny offended voice. He has been to every party in the void and nobody remembers inviting him. His biggest dream is to be in a family photo. So far every photo just shows a hat.","hint":"Only one pair of eyes can see the code. Stand where the eye is."}), // 61
  Object.freeze({"name":"Melody","kind":"Cat Made Of Sound","lore":"Melody is a cat that only exists as an audio file. You cannot see it unless you listen REALLY hard, which is why it wears giant headphones and has a rainbow equalizer glued to its back. Every time it purrs, the bars jump up and down. Its file size is 4 kilobytes and its attitude is 4 gigabytes. Melody once tried to sing a whole song but it got compressed into one note. It has been humming that note ever since, and it is slightly out of tune.","hint":"Close your eyes. Open your ears. The orbs are singing."}), // 62
  Object.freeze({"name":"Noel","kind":"Cat Made Of Nothing","lore":"Noel is the emptiest cat ever discovered. It is made of pure void, so black that looking at it makes your screen feel slightly colder. Only its glowing eyes and a ring of purple sparkles prove it is there at all. Ask it what it ate today: nothing. Ask it what it is thinking: nothing. Ask it what it wants for its birthday: also nothing, but wrapped. Philosophers have written books about it. The books are empty. Noel loved them.","hint":"Seven letters are scattered across the void. Spell what this cat is."}), // 63
  Object.freeze({"name":"Jack","kind":"Bodyguard Cat","lore":"Jack is the most serious cat in the entire void. It wears sunglasses at night, a red tie at all times and an earpiece that only plays whale sounds. Its job is to protect the Duke from dangers like vacuum cleaners, cucumbers and the red laser dot. It has never once smiled on duty. Off duty it also has not smiled. It hides among cardboard copies of itself so nobody knows which one is real, and it gets extremely offended when you pick the wrong one.","hint":"Read the dossier. Only one agent matches it exactly."}), // 64
  Object.freeze({"name":"Murphy","kind":"Podium Cat","lore":"Murphy has given four thousand speeches and every single one starts with \"My fellow cats\". Nobody knows what the rest of the speeches say because the teleprompter is always glitched and the words keep floating away. He stands behind his tiny podium with a microphone that is mostly decorative, because he just yells. His most famous quote is \"The only thing to fear is the vacuum,\" which got a standing ovation from every cat in the room and one confused dog.","hint":"My fellow cats... The teleprompter has the first letters."}), // 65
  Object.freeze({"name":"Bella","kind":"Democracy Cat","lore":"Bella sat in a ballot box once and refused to leave, so now it IS the ballot box. Every vote gets personally inspected, sniffed and occasionally sat on. It wears a shiny I VOTED sticker that it gave to itself. It counts votes very carefully but it can only count to fourteen before it needs a nap. Ballots with a red X get thrown out with a dramatic hiss. Bella says democracy is beautiful, but it would also accept a bribe of one sardine.","hint":"Count every vote. Spoiled ballots (with a red X) do not count."}), // 66
  Object.freeze({"name":"Shadow","kind":"Top Secret Document Cat","lore":"Shadow is so top secret that its own eyes have been redacted with a black bar. It lives flattened inside a manila folder in the presidential safe, stamped with a big red stripe that means DO NOT READ. Nobody knows what is written about it. Rumors say it is the recipe for the perfect tuna casserole. Other rumors say it is just a picture of a cat. Shadow will neither confirm nor deny anything, mostly because it is asleep, and it is very flat.","hint":"The President keeps the safe behind their own portrait."}), // 67
  Object.freeze({"name":"Mittens","kind":"Truth-Telling Candidate","lore":"Mittens has never told a lie in her entire life, which made her the worst debate candidate in void history and also the winner. When asked \"Did you knock the vase off the table?\" she said \"Yes, on purpose, and I would do it again,\" and the crowd went wild. She wears big red mittens because her paws get cold during long speeches, and a little halo she claims she was born with. Her campaign slogan is simply \"I will not lie to you. Feed me.\"","hint":"Honest candidates always tell the truth. Liars never do."}), // 68
  Object.freeze({"name":"Duke","kind":"Leader Of The Free Void","lore":"Duke is the elected leader of the entire nil Void, chosen by a landslide of fourteen votes. It wears a red sash, a gold medal it awarded to itself, cool sunglasses and a dramatic navy cape. Its first executive order was mandatory nap time. Its second executive order was more nap time. It keeps the launch codes for the Catnip Rocket inside a briefcase called the Tuna Football, and it promises to only use the rocket for emergencies, such as running out of treats.","hint":"The launch code is made from the speech, the votes and the safe."}), // 69
  Object.freeze({"name":"Buttons","kind":"Big Red Button Cat","lore":"Buttons is a big red button with ears, and it is the most annoying cat in the void. It has a sign that says DO NOT PRESS, which obviously makes everyone want to press it. The moment you look at it, it giggles HAHAHA and teleports somewhere else. It has been running away from people for six years and has never once been pressed. It does not know what happens if you press it. Honestly, nobody does. Probably confetti. Possibly the end of the universe. Worth it.","hint":"The button is shy. It runs away from anyone who looks at it."}), // 70
  Object.freeze({"name":"Rolf","kind":"Rolling On The Floor Laughing Cat","lore":"Rolf (Rolling On the Floor Laughing) heard one joke in 2009 and has not stopped laughing since. It rolls around on its back, kicking its legs, crying tears of joy and shouting HAHA at absolutely everything. You fell off a platform? HAHA. You picked the wrong door? HAHAHA. You found it after an hour? HAHAHAHA. Nobody remembers what the original joke was. The cat doesn't either. It built a whole maze out of its own laughter, and the louder you follow it, the closer you get.","hint":"Follow the laughter. It only ever gets louder."}), // 71
  Object.freeze({"name":"Ricky","kind":"Cat Laughing At You Specifically","lore":"This cat saw you walk into the Meme Dimension and has not stopped laughing since. Nobody knows what is so funny. Scientists asked it and it just went HAHAHAHA until the scientists also started laughing and then everyone was crying. It is rainbow because it laughed so hard all the colours fell out of a nearby rainbow and stuck to it. It has four evil twins who are FAKES and they laugh too, but the real one is too busy laughing at the fakes to laugh at you. Rude. Iconic. HAHAHAHA.","hint":"Five of them on pillars. Four are fakes. The real one is laughing at somebody else."}), // 72
  Object.freeze({"name":"Skippy","kind":"Cat Doing A Dance Nobody Taught It","lore":"Skippy lives in the secret room under the Infinite Staircase and does the skibidi dance 24 hours a day. What is the skibidi dance? Nobody knows, including Skippy. It just wiggles and says skibidi bop bop yes yes while wearing headphones that are not plugged into anything. Its cap is on backwards because it thinks that makes it faster. It has a gold chain it found in a gumball machine. If you ask it a question it answers skibidi. If you ask it to stop it answers SKIBIDI.","hint":"The Infinite Staircase never ends. One of its steps is unlucky. Check the walls, not the stairs."}), // 73
  Object.freeze({"name":"Sid","kind":"Cat That Wakes Up At 3 AM","lore":"Sid wakes up at 3 AM, takes an ice bath in its water bowl, does 400 push-ups and then reads a book about reading books. It has a briefcase full of nothing. It owns a dumbbell it has never lifted because lifting is for beta cats. It thinks naps are a scam invented by Big Bed. Its sigma rule number one is never stop grinding, which is why its button keeps running away from you. If you catch it seven times it will respect you. Maybe. It is still deciding.","hint":"The GRIND BUTTON in the mall runs away every time you touch it. A sigma never stops."}), // 74
  Object.freeze({"name":"Kiki","kind":"Cat That Only Knows One Song","lore":"Kiki has played the same five notes since the dawn of the Meme Dimension. It wears a blue shirt because a cat in a shirt is legally funnier. It plays a song called SALAD, but it never tells anybody that, it just plays it and stares at you until you play it back. If you play it wrong, it plays it again. Slower. With disappointment. It once played a concert on the giant keyboard and everyone clapped, but they were actually just trying to swat a fly. Kiki still counts it.","hint":"Click the giant speaker to hear its song. Play it back on the home row of the giant keyboard."}), // 75
  Object.freeze({"name":"Willow","kind":"Cat Having A Moment","lore":"Willow is not sad. It is just feeling things. Loudly. With its eyes. It cries when it is happy, when it is hungry, when someone says the word Tuesday, and when it sees a really nice cardboard box. It is so shy that it only comes out if you stand completely still and say nothing for a really long time. Then it sits next to you and cries a puddle and you both just vibe. It is the most emotionally honest cat in the whole game. Please give it a tissue.","hint":"In the Quiet Corner. Stand on the rug. Do not move. Do not move. Do not move..."}), // 76
  Object.freeze({"name":"Dizzy","kind":"Cat That Is Also A Record","lore":"Dizzy sat on a record player in the Vaporwave Mall in 1987 and has been spinning ever since. It does not know how to stop and honestly it does not want to. Its ears pick up radio stations. Its tail plays the bass. If you count every dot in the mall's art gallery correctly, it will spin in your direction, which is a huge honour in spinning culture. It once spun so fast it went back in time by four seconds and used them to eat a snack. Round round round.","hint":"Count every dot on the three gallery boards in the Vaporwave Mall and type the total."}), // 77
  Object.freeze({"name":"Lenny","kind":"Cat That Is Long","lore":"Lenny is long. Then it is longer. Scientists measured it with a ruler and the ruler gave up halfway and went home. Nobody has ever seen both ends of Lenny at the same time, so some people think it is actually two cats sharing one personality. It talks only in blinking lights because it is too far from its own mouth to hear itself. Its favourite word is its own name. Its least favourite word is short. If you ask how long it is, it just says yes.","hint":"The lamp on the tower is blinking a word in Morse code. The chart next to it helps."}), // 78
  Object.freeze({"name":"Puddles","kind":"Cat In A Jar (It Poured Itself)","lore":"Puddles proves that cats are a liquid. It poured itself into a jar and now it is the shape of the jar. If you put it in a teapot it becomes a teapot. It lives in a pitch-black room because it is shy about being see-through. When you walk the right way in the dark it hums higher and higher like a happy kettle. When you walk the wrong way it groans. It has no legs because liquids do not need legs. It once spilled itself on purpose to get out of a bath. Legend.","hint":"In the pitch-black box. Right steps sing higher, wrong steps groan. Follow the song to the end."}), // 79
  Object.freeze({"name":"Rex","kind":"Cat In A Dino Hoodie (Cringe)","lore":"Rawr XD means I love you in dinosaur, according to Rex. It wears a dino hoodie with felt spikes and says nuzzles you to everything, including doors. It has heart eyes permanently. Doctors say it is fine. It keeps its vault locked with a secret word spelled by the first letters of eight numbered signs, because it read that on a forum in 2009 and thought it was very hacker. When you open the vault it screams OwO what is this and then gives you a hug. Rawr.","hint":"Eight numbered signs are spread around the dimension. Their FIRST letters, in order, open the vault."}), // 80
  Object.freeze({"name":"Stella","kind":"Cat From A 1993 Screensaver","lore":"Stella was rendered, not born. It lives inside a pink sunset that never ends, next to a palm tree that is just vibes. It speaks only in wide letters with spaces between them, like H E L L O. It owns sunglasses but they are for the sun inside its own heart. It runs a lights board in the mall that toggles sideways because normal lights out is too mainstream. If you solve it, it plays smooth saxophone for you, but only in your imagination, because that is where the best music lives. Vibes.","hint":"The sideways light board in the Vaporwave Mall. Turn every light OFF."}), // 81
  Object.freeze({"name":"Penny","kind":"Cat That Only Goes Up","lore":"Penny invested its entire allowance into fish crackers and became a billionaire overnight. It wears a suit, a monocle and two diamond paws, because diamond paws never sell. It does not know what a stock is. It just points at a green arrow and says up. Its vault password is hidden in a chain of secret messages across the dimension, each one scrambled a different way, because it heard that is how real banks work. They do not. Penny does not care. Number go up. Cat go up. Up.","hint":"Start at the Meme Market near spawn. Each scrambled note points to the next one."}), // 82
  Object.freeze({"name":"Waffles","kind":"Breakfast Cat That Flies","lore":"Waffles is a waffle with a cat head and it flies over the Rainbow Void leaving a rainbow behind it like a jet. Nobody knows if it is a cat that turned into a waffle or a waffle that learned to meow. It has a pat of butter on its back that never melts and it is VERY proud of that. It hides at the end of a path nobody can see, because it says real breakfast is earned. Somebody drew a map once and hid it inside a giant loaf of bread. Classic breakfast move.","hint":"The path over the Rainbow Void is invisible. Someone hid a map inside the bread."}), // 83
  Object.freeze({"name":"Cosmo","kind":"Cat With Too Many Thoughts","lore":"Cosmo thought so hard its brain grew out of its head and started orbiting itself. It has solved every puzzle in the universe except how to open a can of tuna. It lives on top of a tower made of floating keyboard keys, next to a sliding tile puzzle it invented while sneezing. Its fur is full of stars because it accidentally absorbed a small galaxy during a nap. It speaks only in big words like actually and technically. When you finally reach it, it says you have ascended. Then it asks for tuna.","hint":"Climb the floating keys to the top of the tower and slide the tiles back into order."}), // 84
  Object.freeze({"name":"Finley","kind":"Cat Who Thinks It Is The Ending","lore":"Finley is 100% convinced it is the last cat in the game. It is not. It is cat number 85. Nobody has the heart to tell it. It wears a tiny top hat, carries a sign that says THE END, and bows dramatically every time anyone walks past, even the cleaning robot. It made its own credits and listed itself as director, writer, lead actor, catering AND key grip. It only comes out for the post-credits scene, because real stars make you wait. Fun fact: it has rehearsed its goodbye speech 4,000 times and cries every single time.","hint":"Thanks for watching! Stay seated for the post-credits scene."}), // 85
  Object.freeze({"name":"Lucky","kind":"Numeral Cat","lore":"Scientists asked: what if a cat, but also the number seven? Nobody asked them to ask that. The result is an orange tabby shaped exactly like a 7. It has ears on its top bar, a tail on its bottom, and absolutely no idea how to sit. It is lucky, it is prime, and it is extremely smug about both. It hides behind button 5 for no reason except to annoy people who love the number 7. It thinks 8 is a cat wearing a belt and refuses to talk to 6.","hint":"Seven buttons. Six liars. One truth."}), // 86
  Object.freeze({"name":"Shorty","kind":"Shorts Enjoyer Cat","lore":"This cat found a pair of shorts at the end of the universe and decided they were his whole personality now. They are four sizes too big. They are red with white stripes. They have a drawstring he cannot reach. Whenever anyone tries to catch him he yells EAT MY SHORTS and then immediately gets sad because nobody ever does. He hired six decoy cats to protect him and paid them in letters of the alphabet. They spell something. He will not tell you what. Rude.","hint":"Six decoys each drop a letter. The rude robot wants the word."}), // 87
  Object.freeze({"name":"Nolan","kind":"Professional Troll Cat","lore":"Nolan has said exactly two words in its entire life: lol and no. Usually together. Ask it for directions: lol no. Ask it for a high five: lol no. Ask it if it wants tuna: it says lol no and then eats the tuna anyway. It built a bridge of rude tiles that are not even real and giggled for three days straight. Secretly it respects good manners. If you say please it gets flustered, its sunglasses fog up, and it lets you win. It will deny this. Lol no.","hint":"Mind your manners on the bridge."}), // 88
  Object.freeze({"name":"Snowy","kind":"Professional Quitter Cat","lore":"Snowy has given up on everything. It gave up on chasing lasers. It gave up on knocking cups off tables, halfway through, so the cup is still just wobbling there. It even gave up on being round, but it was too tired to stop, so it is still round. It waves its tiny white flag at anything that moves. The weird part? Giving up totally works for it. It is a Platinum Member of the Quitters' Lounge and has the comfiest beanbag. Winners never quit, it says, but quitters get beanbags.","hint":"Quitters never win. Or do they?"}), // 89
  Object.freeze({"name":"Tuesday","kind":"Abstract Weekday Cat","lore":"This is not a cat. This is the concept of Tuesday that learned to purr. Nobody knows how. It has the vibes of a Tuesday: not as bad as Monday, not as fun as Friday, just sort of there. It lives at the top of a tower made entirely of Monday, which is a horrible place to live. To visit it you must survive Monday morning, a meeting that could have been an email, and overtime. If you ask it what day it is, it says Tuesday. It is always Tuesday. Even on Saturday. Especially on Saturday.","hint":"It's always Monday at the bottom of the tower."}), // 90
  Object.freeze({"name":"Lola","kind":"Cat Stuck At 99%","lore":"Lola has been loading since 2009. Its progress bar has said 99% for so long that the last 1% has become a myth. Some say the last 1% was eaten by a dog. Some say it was never there at all. A little spinning circle orbits its head forever. If you stare at it long enough you can hear a fan whirring. It shattered its final percent into six fragments and hid them all over the End Of Cats, so now it just waits. And waits. Please do not refresh the page.","hint":"Stuck at 99%. Find all six fragments."}), // 91
  Object.freeze({"name":"Rocky","kind":"Keyboard Smasher Cat","lore":"This cat lost a single round of a board game and immediately rage quit life itself. It flattened itself into a pancake shape out of pure anger and snapped its keyboard clean in half. Steam comes out of its ears at all times. It now lies on the floor of the End Of Cats grumbling about lag, even though it was playing a board game. The only thing that calms it down is a light panel arranged into the shape of a cat face. It does not know why. Neither do its therapists.","hint":"Make the board look like the picture."}), // 92
  Object.freeze({"name":"Eddie","kind":"Cat Shaped Like Forever","lore":"Eddie is a cat that goes on forever, which makes bath time a nightmare. Its body loops around itself in a figure eight, so it is technically chasing its own tail for all of eternity. It runs Hilbert's Hotel, a hotel with infinitely many rooms that are always full, and still somehow always has room for one more guest. It counts sheep to fall asleep and never finishes. Its favourite number is aleph null, which it pronounces wrong on purpose just to annoy mathematicians.","hint":"Hilbert's hotel always has room. Ring the right bells."}), // 93
  Object.freeze({"name":"Coco","kind":"Cat Bigger Than Infinity","lore":"Some guy wrote a list of every cat that could possibly exist and said the list was complete. Coco read the list, went down the diagonal, changed one thing in each row, and became a cat that is not on the list. Then it did it again. And again. There are now more Cocos than there are counting numbers, and they are all fighting over the same sunny spot. It is covered in ones and zeros and smells faintly of chalk. It thinks counting to infinity is for beginners.","hint":"Cantor counted past infinity."}), // 94
  Object.freeze({"name":"Mason","kind":"Codebreaker Cat","lore":"Mason invented a guessing game with five pegs and seven colours and has never lost a single round, mostly because it makes up the rules as it goes. It keeps the secret code on its back where it cannot see it, which it calls strategy. It answers every guess with black and white dots and a smug little purr. Black dot means right colour, right place. White dot means right colour, wrong place. No dot means you should feel bad. It once guessed someone's birthday in two tries and has been unbearable ever since.","hint":"Five pegs, seven colours, one big brain."}), // 95
  Object.freeze({"name":"Errol","kind":"Pop-Up Window Cat","lore":"One day a computer tried to show a cat and crashed so hard it showed an error message shaped like a cat instead. The error message liked being a cat more than being an error, so it grew a tail and ran away. It still has a title bar, a close button that does nothing, and an OK button that is not OK. It meows in system beeps. It guards a keypad with a terrible bug that gets worse every time you press a key. If you click its X, it multiplies.","hint":"The keypad has a bug, and the bug gets worse."}), // 96
  Object.freeze({"name":"Gizmo","kind":"Corrupted Text File Cat","lore":"Gizmo sat on a keyboard for nine hours straight and pressed shift so long that it turned into punctuation. Now every time it tries to say its name it comes out as exclamation marks and at-signs. It flickers between three colours because its pixels are not sure which version of it is the real one. It writes everything backwards and in numbers just to be difficult. Its diary is one long line of symbols that only a true nerd could read. It is very proud of this.","hint":"The shift key is stuck. A=1."}), // 97
  Object.freeze({"name":"Ash","kind":"Hash Sign Cat","lore":"Ash is a cat made of four sticks in a tic-tac-toe shape. It is pronounced hashtag cat, pound cat, number sign cat, octothorpe cat or sharp cat depending on who you ask, and it answers to none of them. It lives in the exact middle of a giant maze shaped like itself, which it thinks is a very normal house. It plays tic-tac-toe against itself and loses every time. Its eyes float in the hole in its middle. Nobody knows how it eats. Nobody wants to know.","hint":"In the middle of the #."}), // 98
  Object.freeze({"name":"Fifi","kind":"Hashtag Influencer Cat","lore":"Fifi has 40 million followers and has never posted a single photo without seven filters on it. Hashtag no filter. Hashtag blessed. Hashtag just woke up like this (it did not, it spent three hours on its whiskers). It carries a ring light everywhere, including the bathtub. Its latest post is a nine by nine grid of black and white squares and every comment says what is this. It is a selfie. Obviously. If you colour the squares in correctly you will see its beautiful face. Like and subscribe.","hint":"#NoFilter. #Nonogram."}), // 99
  Object.freeze({"name":"Aiden","kind":"Artificially Intelligent Cat","lore":"Aiden is the 100th cat and it knows it. It was trained on every cat video ever uploaded and now it thinks it IS every cat video. It speaks only in ciphers, does long division for fun, and refuses to talk to anyone who cannot convert a number into base 26 in their head. Its brain floats in a little glass dome and blinks when it is thinking, which is always. It made a captcha that only robots can pass. If you are reading this, you passed. Beep boop. Hello, fellow robot. Never stop.","hint":"Prove you are not a human."}), // 100
]);
